window.ScripturaLexicons.BDAG_PART_0256 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-01\" data-source=\"BDAG\" data-search=\"ὅμως partícula adversativa não obstante; contudo; semelhantemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅμως</td><td>partícula adversativa</td><td>não obstante; contudo; semelhantemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-02\" data-source=\"BDAG\" data-search=\"ὀναίμην forma verbal ver ὀνίνημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀναίμην</td><td>forma verbal</td><td>ver ὀνίνημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-03\" data-source=\"BDAG\" data-search=\"ὄναρ, τό substantivo neutro sonho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄναρ, τό</td><td>substantivo neutro</td><td>sonho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-04\" data-source=\"BDAG\" data-search=\"ὀνάριον, ου, τό substantivo neutro jumento jovem; burrinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνάριον, ου, τό</td><td>substantivo neutro</td><td>jumento jovem; burrinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-05\" data-source=\"BDAG\" data-search=\"ὀνειδίζω verbo injuriar; censurar; repreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνειδίζω</td><td>verbo</td><td>injuriar; censurar; repreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-06\" data-source=\"BDAG\" data-search=\"ὀνειδισμός, οῦ, ὁ substantivo masculino afronta; opróbrio; insulto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνειδισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>afronta; opróbrio; insulto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-07\" data-source=\"BDAG\" data-search=\"ὄνειδος, ους, τό substantivo neutro vergonha; afronta; insulto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄνειδος, ους, τό</td><td>substantivo neutro</td><td>vergonha; afronta; insulto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-08\" data-source=\"BDAG\" data-search=\"ὄνειρον, ου, τό substantivo neutro sonho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄνειρον, ου, τό</td><td>substantivo neutro</td><td>sonho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-09\" data-source=\"BDAG\" data-search=\"Ὀνήσιμος, ου, ὁ nome próprio masculino Onésimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὀνήσιμος, ου, ὁ</td><td>nome próprio masculino</td><td>Onésimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-10\" data-source=\"BDAG\" data-search=\"Ὀνησίφορος, ου, ὁ nome próprio masculino Onesíforo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὀνησίφορος, ου, ὁ</td><td>nome próprio masculino</td><td>Onesíforo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-11\" data-source=\"BDAG\" data-search=\"ὀνικός, ή, όν adjetivo relativo a jumento; mó movida por asno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνικός, ή, όν</td><td>adjetivo</td><td>relativo a jumento; mó movida por asno</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-12\" data-source=\"BDAG\" data-search=\"ὀνίνημι verbo tirar proveito; desfrutar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνίνημι</td><td>verbo</td><td>tirar proveito; desfrutar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-13\" data-source=\"BDAG\" data-search=\"ὄνομα, ατος, τό substantivo neutro nome; pessoa; categoria; reputação; cargo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄνομα, ατος, τό</td><td>substantivo neutro</td><td>nome; pessoa; categoria; reputação; cargo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-14\" data-source=\"BDAG\" data-search=\"ὀνομάζω verbo nomear; pronunciar o nome BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνομάζω</td><td>verbo</td><td>nomear; pronunciar o nome</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-15\" data-source=\"BDAG\" data-search=\"ὀνομαστός, η, ον adjetivo ilustre; célebre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀνομαστός, η, ον</td><td>adjetivo</td><td>ilustre; célebre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-16\" data-source=\"BDAG\" data-search=\"ὄνος, ου substantivo masculino/feminino asno; jumento; jumenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄνος, ου</td><td>substantivo masculino/feminino</td><td>asno; jumento; jumenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-17\" data-source=\"BDAG\" data-search=\"ὄντως advérbio realmente; verdadeiramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄντως</td><td>advérbio</td><td>realmente; verdadeiramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-18\" data-source=\"BDAG\" data-search=\"ὀξίζω verbo azedar; adquirir sabor de vinagre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀξίζω</td><td>verbo</td><td>azedar; adquirir sabor de vinagre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-19\" data-source=\"BDAG\" data-search=\"ὄξος, ους, τό substantivo neutro vinagre de vinho; vinho azedo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄξος, ους, τό</td><td>substantivo neutro</td><td>vinagre de vinho; vinho azedo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0256-20\" data-source=\"BDAG\" data-search=\"ὀξύπτερος, ον adjetivo de asas velozes; falcão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀξύπτερος, ον</td><td>adjetivo</td><td>de asas velozes; falcão</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0256-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅμως</h1><div class=\"entry-meta\"><span>partícula adversativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅμως</span>, partícula adversativa (<span class=\"greek\">ὁμός</span>, «comum»; Hom. e posteriores; Schwyzer II 582f), mesmo assim, não obstante, contudo; reforçada em <span class=\"greek\">ὅμ</span>. <span class=\"greek\">μέντοι</span> (ver <span class=\"greek\">μέντοι</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:42</a>.—O emprego duplo desta palavra nas epístolas de Paulo é peculiar, embora análogo ao uso joanino: <span class=\"greek\">ὅμως</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄψυχα</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">διδόντα</span> … <span class=\"greek\">ἐὰν</span> <span class=\"greek\">διαστολὴν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">φθόγγοις</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δῷ</span>, <span class=\"greek\">πῶς</span> <span class=\"greek\">γνωσθήσεται</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:7</a>, e <span class=\"greek\">ὅμως</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">κεκυρωμένην</span> <span class=\"greek\">διαθήκην</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἀθετεῖ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:15</a>. Em geral, explicam-se essas passagens por hipérbato ou deslocamento de <span class=\"greek\">ὅμως</span>, mantendo-se o sentido «não obstante»; assim, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:15</a>, a tradução seria «mesmo tratando-se apenas do testamento de uma pessoa, ainda assim ninguém o anula» (assim, geralmente, EBurton, ICC, Gal 1920, 178f; cf. passagens como X., Cyr. 5, l, 26 [Kühner-G. II 85f]). Mas, visto que <span class=\"greek\">ὁμ</span>. introduz uma comparação nas duas passagens paulinas (<span class=\"greek\">οὕτως</span> o segue em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:9</a>), é preferível (com B-D-F § 450, 2) entender <span class=\"greek\">ὅμ</span>. como influenciado pelo antigo <span class=\"greek\">ὁμῶς</span>, «igualmente, do mesmo modo» (cf. o emprego ambivalente em Od. 11, 565). A tradução se simplifica muito, podendo-se verter <span class=\"greek\">ὅμ</span>. simplesmente por «semelhantemente, também» (JJeremias, ZNW 52, ’61, 127f, concorda).—DELG s.v. <span class=\"greek\">ὁμό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀναίμην</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀναίμην</span>, ver <span class=\"greek\">ὀνίνημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄναρ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄναρ</span>, <span class=\"greek\">τό</span> (Hom. e outros; Herodas 1, 11; Pherecyd. 24; inscrições; Philo; Jos., Bell. 2, 112, Ant. 2, 63; 10, 195; Ath. 13, 1 <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ὄναρ</span>; mas apenas no nominativo e acusativo singular), sonho; em nossa literatura, apenas em Mt, capítulos 1, 2, 27, na expressão <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄναρ</span>, em sonho (rejeitada por Photius, Lex. p. 149, 25f, como barbarismo [Lob., Phryn. p. 422ff], embora atestada desde a época de Conon [I a.C./I d.C.]: 26 Fgm. 1, 35, 3 Jac., Apolo dá ordens; Strabo 4, 1, 4; Anth. Pal. 11, 263, 1; Diog. L. 10, 32; Eunap. 55; CIG 4331 <span class=\"greek\">χρηματισθεὶς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ὄναρ</span> = «depois de receber um oráculo em sonho» [semelhantemente, de Sarapis, IG XI/4, 13f <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐχρημάτισεν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὕπνον</span>]. Também SIG 1147; 1148/9; IPergamon 357, 8 [Schweizer 157]; IG XII/1, 979, 4f, mas aí significa «como resultado de um sonho» [Dssm., NB 81= BS 253], como Paus. Attic. <span class=\"greek\">λ</span>, 28.—Ver OWeinreich, <span class=\"greek\">θεοὶ</span> <span class=\"greek\">ἐπήκοοι</span>, MAI 37, 1912, 43, n. 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>; 2:12f, 19, 22; 27:19.—EEhrlich, D. Traum im AT ’53, D. Traum im Talmud: ZNW 47, ’56, 133–45; AWikenhauser, Pisciculi=Antike u. Christentum, Erg.-Bd. I ’39, 320–33; outras obras em OSchönberger, Longos 4 ’60, 178, nota sobre Longus 7, 1. Sobre oráculos obtidos durante o sono em santuários, ver JGriffiths, Apuleius of Madauros 75, 139; EDodds, The Greeks and the Irrational ’51, 107–11.—B. 269. New Docs 1, 31; 3, 23. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνάριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνάριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὄναρ</span>; Diphilus Com. [IV/III a.C.] 89 K.; Machon [III a.C.] verso 390 Gow [em Athen. 13, 582c]; Epict. 2, 24, 18; 4, 1, 79; papiros), literalmente «burrinho», mas em muitos casos é claramente um diminutivo apenas quanto à forma (de <span class=\"greek\">ὄνος</span>), jumento, asno (Celsus 4, 43; Vi. Aesopi I cap. 33 p. 304, 1; 4; 9 [Eb,]; POxy 63, 11; daí a possibilidade de um diminutivo duplo, <span class=\"greek\">μικρὸν</span> <span class=\"greek\">ὀναρίδιον</span>, PRyl. 239, 21), provavelmente jumento jovem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:14</a>.—DELG s.v. <span class=\"greek\">ὄναρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνειδίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνειδίζω</span>, imperfeito <span class=\"greek\">ὠνείδιζον</span>; futuro, 3ª pessoa singular, <span class=\"greek\">ὀνειδιεῖ</span>, Sir 18:8; Ps 73, 10, e <span class=\"greek\">ὀνειδίσει</span>, Sir 20:15; 1 aoristo <span class=\"greek\">ὠνείδισα</span>. Passiva: futuro, 3ª pessoa plural, <span class=\"greek\">ὀνειδισθήσονται</span>, Sir 41:7; 1 aoristo <span class=\"greek\">ὠνειδίσθην</span>, LXX (<span class=\"greek\">ὄνειδο</span>; Hom.; Pla. [sobre o contraste com <span class=\"greek\">λοιδορεῖν</span>, ver Pla., Ap. 38c] e posteriores; BGU 1024 VII, 21; PGiss 40 II, 5; LXX; PsSol 2:19; Test12Patr; GrBar 1:2; Philo, Joseph., Just.). ① Criticar de modo que se rebaixe o outro, censurar, injuriar, zombar, cobrir de insultos para envergonhar; com acusativo da pessoa atingida (autores trágicos; Pla., Apol. 30e; Lucian, Tox. 61; Ps 41:11; 54:13 e outros, LXX; Jos., Ant. 14, 430; 18, 360), sobre os insultos e zombarias dirigidos a Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:32</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:3</a> (Ps 68:10), e aos discípulos de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:22</a>. Com duplo acusativo (Soph., Oed. Col. 1002 <span class=\"greek\">ὀν</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">τοιαῦτα</span>; Ael. Aristid. 28, 155 K.=49 p. 542 D.; Heliod. 7, 27, 5): <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λῃσταὶ</span> <span class=\"greek\">ὠνείδιζον</span> <span class=\"greek\">αὐτόν</span>, os ladrões também o insultavam ou escarneciam dele da mesma maneira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:44</a>.—Passiva: <span class=\"greek\">εἰ</span> <span class=\"greek\">ὀνειδίζεσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">Χριστοῦ</span>, se sois insultados por causa do nome de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:14</a>.—Somente como variantes de leitura nas duas passagens seguintes: <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">κοπιῶμεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀνειδιζόμεθα</span>, é por isso (isto é, pelo que precede) que trabalhamos e sofremos afrontas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:10</a>, variante de leitura (em lugar de <span class=\"greek\">ἀγωνιζόμεθα</span>). <span class=\"greek\">εἰς</span> <span class=\"greek\">τί</span> <span class=\"greek\">ὠνείδισάς</span> <span class=\"greek\">με</span>;, por que me censuraste? ou por qual motivo me censuraste? (<span class=\"greek\">ὀν</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, como Appian, Bell. Civ. 2, 104 §430 <span class=\"greek\">ὠνείδισεν</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">δειλίαν</span> = censurou-o por covardia; 5, 54 §224; 5, 96 §400; Jos., Bell. 1, 237), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:34</a> D e Macarius Magnes 1, 12 (o texto apresenta <span class=\"greek\">ἐγκατέλιπες</span>. Ver Harnack, SBBerlAk 1901, 262ff=Studien I ’31, 98ff; JSundwall, D. Zusammensetzung des Mk ’34, 83).—Uma modalidade especial de censura é a insinuação de relutância que muitas vezes acompanha a entrega de um presente (Sextus 339 <span class=\"greek\">ὁ</span> <span class=\"greek\">διδοὺς</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ὀνείδους</span> <span class=\"greek\">ὑβρίζει</span>; diferentemente, Plut., Mor. 64a; ver também Sir 20:15; 41:25.—<span class=\"greek\">ὀν</span>. também pode significar imputar ou censurar alguém por algo, uma espécie de extorsão verbal destinada a obter algo de alguém, por exemplo Maximus Tyr. 5, 7h <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, pela construção de um templo); Deus não procede assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:5</a>. ② Apontar uma falta justificável em alguém, censurar, repreender, com acusativo da pessoa (Pr 25:8; Philo, Fuga 30; Jos., Ant. 4, 189; Just., D. 37, 2 <span class=\"greek\">ὀνειδίζει</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἅγιον</span> e outros) e <span class=\"greek\">ὅτι</span> a seguir para explicar o motivo da censura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:20</a>. Com acusativo da pessoa e <span class=\"greek\">λέγων</span> introduzindo discurso direto (cf. BGU 1141, 23 [14 a.C.] <span class=\"greek\">ὀνειδίζει</span> <span class=\"greek\">με</span> <span class=\"greek\">λέγων</span>), GPt 4:13. Com acusativo da coisa censurada (Isocr., Or. 15, 318, 345a; Herodian 3, 8, 6; Wsd 2:12; Jos., Ant. 10, 139): <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπιστίαν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκληροκαρδίαν</span>, a incredulidade e dureza de coração deles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:14</a>.—Schmidt, Syn. I 136–49. DELG s.v. <span class=\"greek\">ὄνειδο</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνειδισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνειδισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (ver artigo precedente; Dionys. Hal.; Plut., Artax. 22, 12; Vett. Val. 65, 7; 73, 10; LXX; En 103:4; TestSol 26:8 H; Test12Patr; Jos., Ant. 19, 319. Vocábulo tardio: Lob., Phryn. p. 511f), ato de desprezo que produz desonra, afronta, injúria, vergonha, insulto: <span class=\"greek\">εἰς</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">ἐμπίπτειν</span>, cair em desonra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:7</a>. <span class=\"greek\">ἀφεῖλεν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">ὀνειδισμὸν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐχθρῶν</span> <span class=\"greek\">μου</span>, (Deus) retirou de mim a afronta dos meus inimigos, GJs 6:3.—Hb fala do <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, o opróbrio de Cristo, e sustenta que até Moisés tomou sobre si o opróbrio de Cristo, 11:26; também exorta os crentes: <span class=\"greek\">ἐξερχώμεθα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτὸν</span> … <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">φέροντες</span>, saiamos até ele … levando seu opróbrio, 13:13 (<span class=\"greek\">ὀν</span>. <span class=\"greek\">φέρειν</span>, como Ezk 34:29; TestReub 4:7, variante de leitura).—Plural (TestReub. 4:2; TestJud 23:3): <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀν</span>., afrontas, insultos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:3</a> (Ps 68:10; ver <span class=\"greek\">ὀνειδίζω</span> 1). Com <span class=\"greek\">θλίψεις</span>: <span class=\"greek\">ὀνειδισμοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θλίψεσιν</span> <span class=\"greek\">θεατριζόμενοι</span>, expostos publicamente como espetáculo de insultos e perseguições, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:33</a>.—DELG s.v. <span class=\"greek\">ὄνειδο</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄνειδος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄνειδος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e posteriores; Diod S 1, 93, 1; PCairMasp 97 II, 76; LXX; TestReub 4:7; 6:3; TestLevi 10:4; 15:2; EpArist 249; SibOr 3, 607; Philo; Jos., C. Ap. 1, 285 e outros; Just.), perda de reputação ligada a palavras depreciativas, vergonha, afronta, insulto: <span class=\"greek\">ἀφελεῖν</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποις</span>, retirar minha vergonha diante das pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:25</a> (cf. Gen 30:23; Vi Jon 3 [Sch. p. 83, 8; cf. 56, 22; 100, 10]).—Objeto de desprezo (Ps.-Callisth. 2, 18, 4): <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξουθένημα</span> <span class=\"greek\">λαοῦ</span>, 1 Cl 16:15 (Ps 21:7).—B. 1187. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄνειρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄνειρον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span>, e <span class=\"greek\">ὄνειρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (cf. <span class=\"greek\">ὄναρ</span>; Hom. e posteriores; inscrições, papiros, LXX; EpArist 192 e 315; En 13:8 [<span class=\"greek\">ὄνειροι</span>]; TestLevi 8:18; TestAbr; SibOr 3, 293; Philo, Joseph.; Just., A I, 14, 1; Tat.), sonho: <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">φαίνεται</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄνειρον</span>, um anjo do Senhor aparece a ele (José) em sonho, GJs 14:2 (cf. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄναρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>). Cf. a definição de Artem. 1, 2 p. 5 H.: <span class=\"greek\">ὄνειρός</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">κίνησις</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πλάσις</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">πολυσχήμων</span> <span class=\"greek\">σημαντικὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐσομένων</span> <span class=\"greek\">ἀγαθῶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κακῶν</span>, «um sonho é movimento ou formação da alma que indica de muitas maneiras aquilo que será bom ou mau».—DELG s.v. <span class=\"greek\">ὄναρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὀνήσιμος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὀνήσιμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, Onésimo, literalmente «útil» (ver jogo de palavras em Phlm 11), nome encontrado com frequência (inscrições, papiros: Mel. HE 4, 26, 13; referências em Thieme 40; Preisigke, Namenbuch 1922 e bibliografia abaixo), especialmente entre escravos (Menand., Epitr. 1 [p. 975] e outros; Galen, De Optima Doctr. 1 p. 82 JMarquardt [1884] <span class=\"greek\">Ὀν</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Πλουτάρχου</span> <span class=\"greek\">δοῦλος</span>; Lghtf., St. Paul’s Ep. to the Col. and to Phlm. 308f; Hatch 146; Zahn, Einleitung I 3 325). ① Escravo de Filemom, em favor do qual Paulo escreveu a carta a Filemom: Phlm 10; subscrição; <span class=\"greek\">πιστὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγαπητὸς</span> <span class=\"greek\">ἀδελφός</span>, irmão fiel e amado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:9</a>. Cf. subscrição de Col.—ARobertson, Exp. 8th ser., 19, 1920, 29ff; EGoodenough, HTR 22, 1929, 181–83; PHarrison, ATR 32, ’50, 268–93; BHHW II 1343; JNordling, JSNT 41, ’91, 97–119, escravo fugitivo. ② Um Onésimo aparece como bispo de Éfeso em IEph 1:3; 2:1; 6:2; CIG 2983 atesta o nome para essa cidade (cf. EGoodsp., Introd. to the NT ’37, 121f e ali a referência a JKnox).—DELG s.v. <span class=\"greek\">ὀνίνημι</span>. LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὀνησίφορος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὀνησίφορος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (inscrições; Aa [ver índices I 301 e II/2, 344]), Onesíforo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:16</a>; 4:19.—NPlum, TT 3, R. 10, 1919, 193–200.—Cf. DELG s.v. <span class=\"greek\">ὀνίνημι</span>. LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ὄνος</span>; OGI 629, 30; PSI 527, 2 [III a.C.]; BGU 912, 24 [33 d.C.] <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀνικὰ</span> <span class=\"greek\">κτήνη</span>; PGen 23, 4 [70 d.C.]), relativo a asno ou jumento; em nossa literatura somente na combinação <span class=\"greek\">μύλος</span> <span class=\"greek\">ὀν</span>., mó movida pela força de um jumento (portanto, mais pesada do que a utilizada pelas mulheres; ver <span class=\"greek\">μύλος</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a> (ver <span class=\"greek\">λίθος</span> 1c). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a>, variante de leitura (certamente a pedra superior móvel do moinho, e não o próprio animal: <span class=\"greek\">ὄνος</span> <span class=\"greek\">ἀλέτης</span> [X., An. 1, 5, 5; Alexis Com. [IV a.C.], Fgm. 13 K.; Herodas 6, 83; GDI 4992a II, 7 Creta; cf. Ael. Dion. <span class=\"greek\">ο</span>, 23, quanto à aparente aplicação dessa função por Aristóteles à pedra inferior fixa do moinho: Problemata 35, 3, 964b]).—DELG s.v. <span class=\"greek\">ὄνο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνίνημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνίνημι</span> (Hom. e outros; TestSol 13:14 C [?]; Jos., Ant. 16, 242), médio-passivo: 2º aoristo singular <span class=\"greek\">ὠνάσθης</span>, Tob 3:8. Em nossa literatura, somente na voz média (como Sir 30:2 [futuro, 3ª pessoa singular, <span class=\"greek\">ὀνήσεται</span>]; Philo, Agr. 126), receber um favor ou benefício, ou ter algo à própria disposição, tirar proveito de, desfrutar. Apenas no optativo do 2º aoristo, na fórmula (IDefixAudollent 92, 3 [III a.C.] <span class=\"greek\">ὄναιντο</span>; Kaibel 502, 27) <span class=\"greek\">ὀναίμην</span>, que eu tenha alegria, proveito ou benefício, que eu possa desfrutar, com genitivo da pessoa ou coisa que é a origem da alegria (Eur., Hec. 978 <span class=\"greek\">ὀναίμην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παρόντος</span>; Aristoph., Thesm. 469 <span class=\"greek\">οὕτως</span> <span class=\"greek\">ὀναίμην</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τέκνων</span>; Lucian, Philops. 27; Philostrat., Vi. Apoll. 4, 16 p. 135, 3): <span class=\"greek\">ἐγώ</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὀναίμην</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, que eu receba algum benefício de ti no Senhor, Phlm 20. <span class=\"greek\">ὀναίμην</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παντός</span>, que eu tenha continuamente alegria em vós, IEph 2:2; IPol 6:2. <span class=\"greek\">ὀν</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντα</span>, que eu tenha alegria em vós em todos os aspectos, IMg 12. <span class=\"greek\">ὀν</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">θηρίων</span>, que eu desfrute das feras, IRo 5:2; <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὀν</span>., IMg 2; <span class=\"greek\">οὗ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span>, IPol 1:1.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄνομα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄνομα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom. e posteriores). ① Nome próprio de uma entidade, nome. ⓐ Em geral: <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποστόλων</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ταῦτα</span>, estes são os nomes dos apóstolos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:14</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">παρθένων</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀν</span>., os nomes das virgens, Hs 9, 15, 1. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, o nome do pai, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:59</a>. <span class=\"greek\">ὄν</span>. <span class=\"greek\">μοι</span>, subentenda-se <span class=\"greek\">ἐστίν</span>, meu nome é (Od. 9, 366), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:9b</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">σοι</span>;, qual é teu nome?, versículo 9a; com cópula, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:30</a>.—As expressões <span class=\"greek\">ᾧ</span> (<span class=\"greek\">ᾗ</span>) <span class=\"greek\">ὄν</span>., <span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>., <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> (<span class=\"greek\">αὐτῆς</span>), <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῷ</span> (entre parênteses) quase sempre ocorrem sem a cópula (B-D-F § 128, 3; Rob. 395): <span class=\"greek\">ᾧ</span> (<span class=\"greek\">ᾗ</span>) <span class=\"greek\">ὄν</span>. (Sb 7573, 13 [116 d.C.]; Demetr.: 722 Fgm. 1, 5 Jac.; Just., A I, 53, 8 <span class=\"greek\">ᾧ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">Λώτ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:26</a>, 27a; 2:25; 8:41; 24:13, 18, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:6</a>.—<span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. (sem verbo, como BGU 344, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:32</a>. Cf. <span class=\"greek\">ὧν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">βίβλῳ</span> <span class=\"greek\">ζωῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a> (<span class=\"greek\">ὧν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀν</span>. é fórmula [Dssm., LO 95=LAE 121]. Ver especialmente BGU 432 II, 3 <span class=\"greek\">ὧν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">βιβλιδίῳ</span> <span class=\"greek\">δεδήλωται</span>).—<span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:5b</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">παρθένου</span> <span class=\"greek\">Μαριάμ</span>, versículo 27b.—<span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῷ</span> (Demosth. 32, 11 <span class=\"greek\">Ἀριστοφῶν</span> <span class=\"greek\">ὄνομ</span>’ <span class=\"greek\">αὐτῷ</span>; Dionys. Hal. 8, 89, 4; Aelian, NA 8, 2 <span class=\"greek\">γυνὴ</span> … <span class=\"greek\">Ἡρακληὶς</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῇ</span>; LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:6</a>; 3:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">καθήμενος</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">αὐτοῦ</span> (isto é, <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἵππου</span>), <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῷ</span> (<span class=\"greek\">ὁ</span>) <span class=\"greek\">θάνατος</span>, o que estava montado nele (no cavalo) tinha por nome (a) Morte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:8</a>; cf. 9:11a.—Com cópula: <span class=\"greek\">ἦν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">δούλῳ</span> <span class=\"greek\">Μάλχος</span>, e o servo se chamava Malco, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:10</a> (POxy 465, 12 <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">κραταιὸς</span> <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">Νεβύ</span>, <span class=\"greek\">μηνύει</span>; Jos., Ant. 19, 332). <span class=\"greek\">ἄγγελος</span> … , <span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἐστιν</span> <span class=\"greek\">Θεγρί</span>, anjo … cujo nome é Tegri, Hv 4, 2, 4.—É muito frequente o dativo <span class=\"greek\">ὀνόματι</span>, chamado, de nome (X., Hell. 1, 6, 29 <span class=\"greek\">Σάμιος</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">Ἱππεύς</span>; Tob 6:11 BA; 4 Macc 5:4; Just., D. 85, 6; 115, 3; B-D-F § 160; 197; Rob. 487): <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Σίμωνα</span>, um homem chamado Simão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:32</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:5a</a>; 5:27; 10:38; 16:20; 23:50; 24:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:1</a>, 34; 8:9; 9:10–12, 33, 36; 10:1; 11:28; 12:13; 16:1, 14; 17:34; 18:2, 7, 24; 19:24; 20:9; 21:10; 27:1; 28:7; MPol 4. Também o acusativo <span class=\"greek\">τοὔνομα</span> (sobre a crase, ver B-D-F § 18; Mlt-H. 63; FPreisigke, Griech. Urkunden des ägypt. Mus. zu Kairo [1911] 2, 6 <span class=\"greek\">γυνὴ</span> <span class=\"greek\">Ταμοῦνις</span> <span class=\"greek\">τοὔνομα</span>; Diod S 2, 45, 4 <span class=\"greek\">πόλιν</span> <span class=\"greek\">τοὔνομα</span> <span class=\"greek\">Θ</span>.; Lucian, Dial. Deor. 3; Philo, Leg. All. 1, 68; Jos., Ant. 7, 344, Vi. 382), chamado, de nome (acusativo como em X. e outros, também 2 Macc 12:13; Demetr.: 722 Fgm. 1, 5 Jac. <span class=\"greek\">υἱὸν</span> <span class=\"greek\">ὄ</span>. <span class=\"greek\">Δάν</span>.—B-D-F § 160; Rob. 487), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:57</a>. (Cf. <span class=\"greek\">ὄν</span>. em geral como «modo de expressão»: <span class=\"greek\">εἰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διάφορα</span> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ἀλλ</span>’ … <span class=\"greek\">οἰκείαν</span> … <span class=\"greek\">δέχεται</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">νόησιν</span>, embora haja várias maneiras de exprimi-lo, a expressão tem, ainda assim, um sentido próprio e definido, Did., Gen. 86, 22 [acerca de diferentes metáforas e imagens da alma]). ⓑ Usado com verbos. <span class=\"greek\">α</span>. Como objeto: <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἔχειν</span>, Did., Gen. 29, 6, ter por nome, receber o nome, chamar-se: <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἔχει</span> <span class=\"greek\">Ἀπολλύων</span>, chama-se Apoliom, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:11b</a> (nesse caso, o nome <span class=\"greek\">Ἀ</span>. aparece de forma independente, no nominativo; B-D-F § 143; Rob. 458). <span class=\"greek\">καλεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινος</span>, seguido do nome no acusativo (segundo o uso hebraico; B-D-F § 157, 2; Rob. 459): <span class=\"greek\">καλέσεις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Ἰησοῦν</span>, dar-lhe-ás o nome Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:31</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:25</a>. <span class=\"greek\">καλέσεις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Ἰωάννην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:13</a>. <span class=\"greek\">καλέσουσιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Ἐμμανουήλ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a> (Is 7:14). <span class=\"greek\">διδόναι</span>, GJs 6:2. Passiva com o nome no nominativo (cf. GrBar 6:10 <span class=\"greek\">Φοῖνιξ</span> <span class=\"greek\">καλεῖται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span>): <span class=\"greek\">ἐκλήθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Ἰησοῦς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:13</a>. Também <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀστέρος</span> <span class=\"greek\">λέγεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">῎</span> <span class=\"greek\">Αψινθος</span>, o nome da estrela é chamado Absinto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:11</a>.—<span class=\"greek\">ἐπιθεῖναι</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινι</span>, seguido do nome no acusativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:16f</a>; cf. 12:8f; <span class=\"greek\">κληρονομεῖν</span> <span class=\"greek\">ὄν</span>., receber um nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:4</a> = 1 Cl 36:2. <span class=\"greek\">κληροῦσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">ὄν</span>., obter o mesmo nome (ver <span class=\"greek\">κληρόω</span> 2), MPol 6:2.—<span class=\"greek\">τὰ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐγγέγραπται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">οὐρανοῖς</span>, vossos nomes estão inscritos nos céus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:20</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:8</a>; 17:8. <span class=\"greek\">ἐξαλείψω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτῶν</span>, apagarei o nome deles, 1 Cl 53:3 (Dt 9:14); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:5a</a> (talvez deva ser classificado em 4 abaixo); ver <span class=\"greek\">ἐξαλείφω</span>. <span class=\"greek\">β</span>. De outra maneira (<span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">καλέσει</span>, mas se alguém for assim denominado, Hippol., Ref. 6, 20, 2): <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">καλεῖται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">τούτῳ</span>, aquele que assim é chamado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.61\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:61</a>. <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">καλούμενος</span> <span class=\"greek\">Ζακχαῖος</span>, um homem chamado pelo nome Zaqueu, 19:2. <span class=\"greek\">καλεῖν</span> <span class=\"greek\">τι</span> (isto é, <span class=\"greek\">παιδίον</span>) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματί</span> <span class=\"greek\">τινος</span>, dar a alguém o nome de outra pessoa, 1:59. Cf. IMg 10:1. Isso conduz a ⓒ emprego com preposições: <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὀνόματος</span> (Ctesias, Ind. p. 105 M.; Diod S 13, 15, 1; 37, 15, 2; Appian, Mithrid. 59, §243, Bell. Civ. 3, 21 §77; 4, 73 §310; PGM 4, 2973; Jos., Ant. 2, 275), pelo nome, individualmente, um a um (de modo que ninguém se perca na multidão): <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">πάντας</span> <span class=\"greek\">ζήτει</span>, IPol 4:2. <span class=\"greek\">ἀσπάζομαι</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὀνόματος</span>, 8:2. <span class=\"greek\">πάντες</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">συνέρχεσθε</span> (paralelo a <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἄνδρα</span>), IEph 20:2.—<span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄν</span>., pelo nome, individualmente (Diod S 16, 44, 2; Gen 25:13; EpArist 247; Jos., Bell. 7, 14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:3</a> (New Docs 3, 77f; animais chamados individualmente pelo nome: Ps.-Aristot., Mirabil. 118.—HAlmqvist, Plut. u. das NT ’46, 74). Especialmente em saudações (BGU 27, 18 [II d.C.] <span class=\"greek\">ἀσπάζομαι</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">φιλοῦντάς</span> <span class=\"greek\">σε</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄν</span>.; POxy 1070, 46; papiro em Dssm., LO 160/1, linha 14f [LAE 193, linha 15, nota 21]; New Docs 3, 77f), 3J 15; ISm 13:2b. <span class=\"greek\">ῥάβδους</span> <span class=\"greek\">ἐπιγεγραμμένας</span> <span class=\"greek\">ἑκάστης</span> <span class=\"greek\">φυλῆς</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄν</span>., varas inscritas, cada uma com o nome de uma tribo, 1 Cl 43:2b. ⓓ Empregado em associação com Deus e Jesus. Sobre o significado do Nome Divino na história das religiões, ver FGiesebrecht, Die atl. Schätzung des Gottesnamens 1901; Bousset, Rel. 3 309ff; ADieterich, Eine Mithrasliturgie 1903, 110ff; FConybeare, JQR 8, 1896; 9, 1897, especialmente 9, 581ff; JBoehmer, Das bibl. «im Namen» 1898, BFCT V 6, 1901, 49ff, Studierstube 2, 1904, 324ff; 388ff; 452ff; 516ff; 580ff; BJacob, Im Namen Gottes 1903; WHeitmüller, «Im Namen Jesu» 1903; WBrandt, TT 25, 1891, 565ff; 26, 1892, 193ff; 38, 1904, 355ff; RHirzel, Der Name: ASG 36, 2, 1918; Schürer III 4 409–11; HObbink, De magische betekenis van den naam inzonderheid in het oude Egypte 1925; OGrether, Name u. Wort Gottes im AT ’34; HHuffman, Name: 1148–52.—A crença na eficácia do nome é extremamente antiga; suas origens remontam aos tempos mais remotos e às formas mais primitivas de vida intelectual e religiosa. Ela demonstrou vitalidade extraordinária. Também na época de nossa literatura, tanto dentro como fora da nova comunidade de crentes, via-se no nome algo real, uma parcela da própria natureza da personalidade designada, que exprimia suas qualidades e poderes. Por conseguinte, os nomes, especialmente os nomes sagrados, eram reverenciados e empregados em práticas costumeiras e rituais (<span class=\"greek\">σέβεσθαι</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ὀνόματα</span>, Theoph. Ant. 1, 9 [p. 76, 7]), inclusive na magia. Na tradição israelita, a máxima reverência se dirigia ao santo nome de Deus e às numerosas paráfrases ou substitutos desse nome; os nomes dos anjos e patriarcas ocupavam posição secundária. As práticas sincréticas do período reverenciavam nomes de deuses, demônios e heróis, e até palavras mágicas desprovidas de sentido, mas dotadas de som misterioso. Os judeu-cristãos reverenciavam e empregavam o nome de Deus e, naturalmente, o nome de Jesus. Sobre magia em círculos judaicos, ver Schürer III 342–79; para o período neotestamentário em geral, ver MSmith, Clement of Alexandria and a Secret Gospel of Mark ’73, 195–230. Os nomes de Deus e de Jesus. <span class=\"greek\">α</span>. Em associação com atributos: <span class=\"greek\">διαφορώτερον</span> <span class=\"greek\">ὄν</span>., nome mais excelente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:4</a> = 1 Cl 36:2 (<span class=\"greek\">διάφορος</span> 2). <span class=\"greek\">ἅγιον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span>, santo é o seu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:49</a> (cf. Ps 110:9; Lev 18:21; 22:2; PGM 3, 570; 627; 4, 1005; 3071; 5, 77; 13, 561 <span class=\"greek\">μέγα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἅγιον</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">μεγαλοπρεπὲς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span>, o seu majestoso e santo nome, 1 Cl 64; <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔνδοξον</span> <span class=\"greek\">ὄν</span>., o nome grande e glorioso, Hv 4, 1, 3; 4, 2, 4 (sobre <span class=\"greek\">ἔνδοξον</span> <span class=\"greek\">ὄν</span>., cf. EPeterson, <span class=\"greek\">Εἷ</span> <span class=\"greek\">θεός</span> 1926, 282.—<span class=\"greek\">ὄν</span>. <span class=\"greek\">μέγα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἅγ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔνδ</span>.: PGM 13, 183f; 504f). <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαυμαστὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔνδοξον</span> <span class=\"greek\">ὄν</span>., Hs 9, 18, 5; <span class=\"greek\">τὸ</span> <span class=\"greek\">πανάγιον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔνδοξον</span> <span class=\"greek\">ὄν</span>., 1 Cl 58:1a; <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντοκράτορος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐνδόξου</span> <span class=\"greek\">ὄν</span>., Hv 3, 3, 5; <span class=\"greek\">τὸ</span> <span class=\"greek\">πανάρετον</span> <span class=\"greek\">ὄν</span>., 1 Cl 45:7; <span class=\"greek\">τῷ</span> <span class=\"greek\">παντοκράτορι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐνδόξῳ</span> <span class=\"greek\">ὀνόματι</span>, 60:4; <span class=\"greek\">τὸ</span> <span class=\"greek\">ὁσιώτατον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγαλωσύνης</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὄν</span>., 58:1b. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">θαυμαστὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσι</span>, meu nome é maravilhoso entre as nações, D 14:3 (cf. Mal 1:14). As palavras <span class=\"greek\">ὄν</span>. <span class=\"greek\">θεοπρεπέστατον</span>, IMg 1:2, são difíceis de interpretar (ver Hdb. ad loc.; <span class=\"greek\">θεοπρεπής</span> b). <span class=\"greek\">β</span>. Em associação com verbos: <span class=\"greek\">ἁγιάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>., santificar o nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:9</a> (AFridrichsen, Helligt vorde dit naun: DTT 8, 1917, 1–16). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a>; D 8:2 (<span class=\"greek\">ἁγιάζω</span> 3). <span class=\"greek\">βλασφημεῖν</span> (ver esse verbete, b <span class=\"greek\">γ</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>., blasfemar contra o nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:6</a>; 16:9; na passiva, <span class=\"greek\">βλασφημεῖται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. (Is 52:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:24</a>; 2 Cl 13:1f, 4; ITr 8:2. <span class=\"greek\">βλασφημίας</span> <span class=\"greek\">ἐπιφέρεσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, trazer blasfêmia sobre o nome do Senhor, 1 Cl 47:7. <span class=\"greek\">πφοσέθηκαν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">βλασφημίαν</span>, Hs 6, 2, 3; <span class=\"greek\">βεβηλοῦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>., profanar o nome, 8, 6, 2 (ver <span class=\"greek\">βεβηλόω</span>). <span class=\"greek\">ἀπαγγελῶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφοῖς</span> <span class=\"greek\">μου</span>, anunciarei o nome a meus irmãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:12</a> (cf. Ps 21:23). <span class=\"greek\">ὅπως</span> <span class=\"greek\">διαγγελῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span>, para que meu nome seja proclamado em toda a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:17</a> (Ex 9:16). <span class=\"greek\">δοξάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. (<span class=\"greek\">σου</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> etc.), glorificar o nome (teu, do Senhor, de Deus etc.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:4</a>; 1 Cl 43:6; IPhld 10:1; Hv 2, 1, 2; 3, 4, 3; 4, 1, 3; Hs 9, 18, 5 (ver <span class=\"greek\">δοξάζω</span> 1; cf. GJs 7:2; 12:1 [com referência ao nome de Maria]). <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἐνδοξασθῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span>, para que o nome de nosso Senhor Jesus seja glorificado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:12</a>. <span class=\"greek\">ἐλπίζειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>., esperar no nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:21</a> (variantes de leitura <span class=\"greek\">ἐν</span> ou <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>.; a passagem de base, Is 42:4, tem <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>.). <span class=\"greek\">ἐπικαλεῖσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">κυρίου</span> (como PsSol 6:1) ou <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">σου</span> etc. (referido a Deus ou Cristo), invocar o nome do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:21</a> (Jo 3:5); 9:14, 21; 22:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:13</a> (Jo 3:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:2</a>. <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ἐπικεκλημένη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μεγαλοπρεπὲς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span>, pessoa que invoca o seu nome excelso e santo, 1 Cl 64.—Na passiva: <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οὓς</span> <span class=\"greek\">ἐπικέκληται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:17</a> (Am 9:12). <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπικληθὲν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span>, o belo nome que foi invocado sobre vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:7</a> (sobre <span class=\"greek\">καλὸν</span> <span class=\"greek\">ὄν</span>., cf. Sb 343, 9 e o grafito pompeiano em Dssm., LO 237 [LAE 276]). <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπικαλούμενοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span>, todos os que são chamados pelo nome (do Senhor), Hs 9, 14, 3; cf. <span class=\"greek\">οἱ</span> <span class=\"greek\">κεκλημένοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, os chamados pelo nome do Senhor, 8, 1, 1. <span class=\"greek\">ἐπαισχύνεσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">κυρίου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπικληθὲν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>, envergonhar-se do nome invocado sobre eles, 8, 6, 4. <span class=\"greek\">ὁμολογεῖν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span>, louvar o seu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:15</a> (cf. PsSol 15:2 <span class=\"greek\">ἐξομολογήσασθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">σου</span>). <span class=\"greek\">ὀνομάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">κυρίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a> (Is 26:13). <span class=\"greek\">ψάλλειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">σου</span>, cantar louvores a teu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:9</a> (Ps 17:50). <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λάβῃς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ματαίῳ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">κυρίου</span>, não tomarás em vão o nome do Senhor, 19:5 (Ex 20:7; Dt 5:11).—Embora, nos exemplos anteriores, o nome muitas vezes seja praticamente inseparável daquele que o porta, isso talvez seja ainda mais evidente nos casos seguintes, nos quais o nome aparece quase como representação da Divindade, manifestação palpável da natureza divina (Quint. Smyrn. 9, 465: Polidarius, ao curar, invoca <span class=\"greek\">οὔνομα</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἑοῖο</span>, «o nome de seu pai» [Asclépio]; <span class=\"greek\">τοσοῦτον</span> … <span class=\"greek\">δύναται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμόνων</span>, Orig., C. Cels. 1, 56, 11; Dt 18:7; 3 Km 8:16; Ps 68:37; Zech 13:2 <span class=\"greek\">ἐξολεθρεύσω</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">εἰδώλων</span>; Zeph 1:4; PsSol 7:6; Just., D. 121, 3 <span class=\"greek\">ὑποτάσσεσθαι</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὀν</span>.): o «nome» de Deus é <span class=\"greek\">ἀρχέγονον</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">κτίσεως</span>, princípio de toda a criação, 1 Cl 59:3. Analogamente, <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μέγα</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">βαστάζει</span>, o nome do Filho de Deus é grande e sustenta todo o mundo, Hs 9, 14, 5. <span class=\"greek\">λατρεύειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παναρέτῳ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span>, adorar o nome excelentíssimo (do Altíssimo), 1 Cl 45:7. <span class=\"greek\">ὑπακούειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παναγίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐνδόξῳ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span>, obedecer ao seu nome santíssimo e glorioso, 58:1a. <span class=\"greek\">ὑπήκοον</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παντοκρατορικῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παναρέτῳ</span> <span class=\"greek\">ὀν</span>., 60:4. <span class=\"greek\">κηρύσσειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, proclamar o nome do Filho de Deus, Hs 9, 16, 5. <span class=\"greek\">ἐπιγινώσκειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, reconhecer o nome do Filho de Deus, 9, 16, 7. <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">σου</span>, temer teu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>. <span class=\"greek\">φανεροῦν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">σου</span>, manifestar teu nome a alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:6</a>. <span class=\"greek\">γνωρίζειν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">σου</span>, fazer conhecido teu nome a alguém, versículo 26. <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span>, crer no nome do Filho (de Deus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:23</a>. Também <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. (ver <span class=\"greek\">γ</span> <span class=\"hebrew\" dir=\"rtl\">ב</span> adiante e <span class=\"greek\">πιστεύω</span> 2a <span class=\"greek\">β</span>).—Acerca do nome portado pelos seguidores de Jesus Cristo (cf. Theoph. Ant. 1, 1 [p. 58, 13]): <span class=\"greek\">κρατεῖς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span>, tu te apegas ao meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a>. O mesmo sentido se aplica às expressões: <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span>, Hs 9, 12, 4; 8; 9, 13, 2a; 7. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βαστάσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">ἐθνῶν</span>, levar meu nome perante os gentios, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:15</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἡδέως</span> <span class=\"greek\">βαστάζειν</span>, portar o nome com alegria, Hs 8, 10, 3; cf. 9, 28, 5b. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φορεῖν</span>, portar o nome do Filho de Deus, 9, 13, 3; 9, 14, 5f; 9, 15, 2; cf. 9, 13, 2b. Os cristãos recebem esse nome no batismo: <span class=\"greek\">πρὶν</span> <span class=\"greek\">φορέσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">νεκρός</span> <span class=\"greek\">ἐστιν</span>, antes de portar o nome do Filho de Deus (conferido ao candidato no batismo), a pessoa está morta, 9, 16, 3. Sobre dissimuladores e falsos mestres: <span class=\"greek\">ὄν</span>. <span class=\"greek\">μὲν</span> <span class=\"greek\">ἔχουσιν</span>, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">κενοί</span> <span class=\"greek\">εἰσιν</span>, eles têm o nome (cristão), mas carecem de fé, 9, 19, 2. Sobre cristãos apenas aparentes: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑποκρίσει</span> <span class=\"greek\">φέροντες</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, os que portam fingidamente o nome do Senhor, Pol 6:3. <span class=\"greek\">δόλῳ</span> <span class=\"greek\">πονηρῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">περιφέρειν</span>, ostentar o nome com engano perverso (evidentemente acerca de pregadores itinerantes), IEph 7:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἐπαισχύνονται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">αὐτῶν</span>, envergonham-se do nome de seu Senhor, Hs 9, 21, 3. Mais explicitamente: <span class=\"greek\">ἐπαισχύνονται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">φορεῖν</span>, envergonham-se de portar seu nome, 9, 14, 6. <span class=\"greek\">γ</span>. Usado com preposições. <span class=\"hebrew\" dir=\"rtl\">א</span>. Com <span class=\"greek\">διά</span> e genitivo: <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματός</span> <span class=\"greek\">μου</span> <span class=\"greek\">πιστεύειν</span>, PtK 3 p. 15 linha 12; <span class=\"greek\">σωθῆναι</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐνδόξου</span> <span class=\"greek\">ὀν</span>., ser salvo mediante o nome grande e glorioso, Hv 4, 2, 4. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰσελθεῖν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> (<span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>), entrar no reino de Deus mediante o nome do Filho (de Deus), Hs 9, 12, 5. <span class=\"greek\">ἄφεσιν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span>, receber perdão dos pecados mediante seu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:43</a> (cf. Just., D. 11, 4 e outros). <span class=\"greek\">σημεῖα</span> … <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. … <span class=\"greek\">Ἰησοῦ</span>, sinais … acontecerem pelo poder do nome de Jesus, 4:30. Diferentemente, <span class=\"greek\">παρακαλεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, exortar alguém pelo nome (= invocando o nome) do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:10</a>.—Com <span class=\"greek\">διά</span> e acusativo: <span class=\"greek\">μισούμενοι</span> … <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span>, odiados por causa de meu nome (isto é, por portardes esse nome), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:22</a>; 24:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:17</a> (Just., A I, 4, 2 e outros). <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span>, fazer algo a alguém por causa de meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:21</a>. <span class=\"greek\">ἀφέωνται</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἁμαρτίαι</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span>, vossos pecados são perdoados por causa do nome (de Jesus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:12</a>. <span class=\"greek\">βαστάζειν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">μου</span>, suportar (sofrimentos) por causa de meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:3</a> (ver <span class=\"greek\">βαστάζω</span> 2b <span class=\"greek\">β</span>). <span class=\"greek\">πάσχειν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>., sofrer por causa do nome (também com genitivo, como <span class=\"greek\">αὐτοῦ</span>), Pol 8:2; Hv 3, 2, 1b; Hs 9, 28, 3. <span class=\"hebrew\" dir=\"rtl\">ב</span>. Com <span class=\"greek\">εἰς</span>: por vezes, evidentemente como tradução do rabínico <span class=\"hebrew\" dir=\"rtl\">לְשֵׁם</span>, com referência a, tendo em vista: <span class=\"greek\">δέχεσθαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., receber alguém por consideração a Jesus Cristo, IRo 9:3. <span class=\"greek\">δύο</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">συνηγμένοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμὸν</span> <span class=\"greek\">ὄν</span>., dois ou três reunidos tendo-me em mente, isto é, sendo eu a razão de sua reunião, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:20</a>; mas também aqui teve alguma influência o outro significado (ver <span class=\"hebrew\" dir=\"rtl\">ג</span> abaixo): «ao mencionar» ou «ao invocar meu nome». <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγάπης</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">ἐνεδείξασθε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span> (isto é, <span class=\"greek\">θεοῦ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:10</a>, pode significar o amor que demonstrastes para com ele, isto é, por causa dele, ou conter a fórmula frequentemente atestada na linguagem jurídica e comercial helenística (ver Mayser II/2 p. 415; Dssm., B 143ff, NB 25, LO 97f [BS 146f; 197; LAE 121]; Heitmüller, op. cit. 100ff; FPreisigke, Girowesen im griech. Ägypt. 1910, 149ff. Sobre a LXX, ver Heitmüller 110f; JPsichari, Essai sur le Grec de la Septante 1908, 202f): <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινος</span>, para o nome = para a conta (identificada pelo nome). Assim, as obras de amor, embora realizadas para pessoas, são dedicadas a Deus.—O conceito de dedicação também é, com toda probabilidade, bastante importante para compreender a expressão <span class=\"greek\">βαπτίζειν</span> <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινος</span>. Pelo batismo <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ὄν</span>. <span class=\"greek\">τ</span>., os batizados tornam-se propriedade daquele cujo nome portam, ficando sob sua proteção especialmente dedicada. Um fator adicional, em certa medida, pode ser o sentido de <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. = «com a menção do nome» (cf. Herodian 2, 2, 10; 2, 13, 2 <span class=\"greek\">ὀμνύναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινος</span>; Cyranides p. 57, 1 <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινος</span>; 60, 18= <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τ</span>.; 62, 13. Outro exemplo em Heitmüller 107): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:16</a>; 19:5; D 7:1, (3); 9:5; Hv 3, 7, 3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a>, 15. Ver <span class=\"greek\">βαπτίζω</span> 2c e Silva New, Beginn. I/5, ’33, 121–40.—<span class=\"greek\">πιστεύειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τινος</span>, crer no nome de alguém, isto é, confiar que esse nome (mais propriamente no sentido de título, cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:9</a>) é portado legitimamente e expressa o que a pessoa realmente é, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:12</a>; 2:23; 3:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:13</a>. <span class=\"hebrew\" dir=\"rtl\">ג</span>. Com <span class=\"greek\">ἐν</span>: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span>, referido a Deus ou Jesus, significa na grande maioria dos casos «com a menção do nome», «ao pronunciar ou invocar o nome» (PsSol 11:8; JosAs 9:1; Just., D. 35, 2 e outros; não se encontrou emprego correspondente na literatura grega geral; mas cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑψίστου</span> <span class=\"greek\">θεοῦ</span>, Hippol., Ref. 9, 15, 6.—Heitmüller p. 13ff, especialmente 44; 49). Em muitas passagens, parece tratar-se de uma fórmula. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">δαιμόνια</span>, expulsar demônios em nome de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:38</a>; 16:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:49</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">δαιμόνια</span> <span class=\"greek\">ὑποτάσσεται</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">σου</span>, os demônios se submetem a nós quando se menciona teu nome, 10:17. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span>, fazer algo em nome de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:7</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:17</a>. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:25</a> (mas ver abaixo). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰησοῦ</span> … <span class=\"greek\">οὗτος</span> <span class=\"greek\">παρέστηκεν</span> <span class=\"greek\">ὑγιής</span>, em nome de Jesus … este homem está aqui curado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:10</a>. <span class=\"greek\">ὄν</span>. … <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">σωθῆναι</span> <span class=\"greek\">ἡμᾶς</span>, nome … pelo qual devemos ser salvos, versículo 12. <span class=\"greek\">παραγγέλλω</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., ordeno-te em nome de Jesus Cristo, 16:18; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>; IPol 5:1. <span class=\"greek\">σοὶ</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, eu te digo em nome do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:10</a> D. Pedro, ao realizar uma cura, diz: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">περιπάτει</span>, em nome de Jesus Cristo, anda, 3:6 (ver Heitmüller 60). Os presbíteros devem ungir os enfermos com azeite <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, invocando o nome do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:14</a>.—Acerca dos profetas: <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, falar em nome do Senhor, 5:10. <span class=\"greek\">παρρησιάζεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰησοῦ</span>, falar com ousadia ao anunciar o nome de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:27f</a>. <span class=\"greek\">βαπτίζεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χ</span>., ser batizado ou fazer-se batizar mencionando o nome de Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:38</a>, variante de leitura; 10:48. Num batismo, <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">χριστοῦ</span> <span class=\"greek\">Ἰησοῦ</span>, AcPl Ha 3, 32. <span class=\"greek\">αἰτεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span> (= <span class=\"greek\">Ἰησοῦ</span>), pedir ao Pai usando meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:16</a>; cf. 14:13, 14; 16:24, 26. A essas últimas passagens pertence o versículo 23: (<span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span>) <span class=\"greek\">δώσει</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, (o Pai) vos dará quando mencionardes meu nome. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">πέμψει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, o Espírito que o Pai enviará quando se empregar meu nome, 14:26. Agradecer a Deus <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χρ</span>., mencionando o nome de Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:20</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">γόνυ</span> <span class=\"greek\">κάμψῃ</span>, para que, ao ser mencionado o nome de Jesus, se dobre todo joelho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:10</a>. <span class=\"greek\">χαίρετε</span>, <span class=\"greek\">υἱοί</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, saudações, meus filhos, enquanto invocamos o nome do Senhor, 1:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐρχόμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, quem vem mencionando o nome do Senhor (e assim demonstra ser cristão), D 12:1. <span class=\"greek\">ἀσπάζεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., saudar pronunciando o nome de Jesus Cristo, com acusativo da pessoa ou coisa saudada, IRo, inscrição; ISm 12:2. Receber uma congregação <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">θεοῦ</span>, IEph 1:3. <span class=\"greek\">συναχθῆναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰ</span>., reunir-se e invocar o nome do Senhor Jesus = como congregação cristã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:4</a>. <span class=\"greek\">μόνον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., apenas (seja isso feito) ao invocar o nome de Jesus Cristo, ISm 4:2.—Não muito distantes estão os casos em que se traduz <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. por «por meio de» ou «pelo nome» (ver <span class=\"greek\">ἐν</span> 4c); o efeito realizado pelo nome decorre de pronunciá-lo: <span class=\"greek\">ἀπελούσασθε</span>, <span class=\"greek\">ἡγιάσθητε</span>, <span class=\"greek\">ἐδικαιώθητε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., fostes lavados, santificados e justificados no nome do Senhor Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:11</a>. <span class=\"greek\">ζωὴν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span> (= <span class=\"greek\">Ἰησοῦ</span>), ter vida em seu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:31</a>. <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. (<span class=\"greek\">θεοῦ</span>), guardar alguém no nome (de Deus), 17:11f.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>., por ordem (de), por incumbência (de): <span class=\"greek\">ἔργα</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, realizar obras por ordem do Pai, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:25</a> (mas ver acima). <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, vir em nome do Pai, 5:43a; em contraste, <span class=\"greek\">ἔρχ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἰδίῳ</span>, vir em seu próprio nome, versículo 43b. <span class=\"greek\">εὐλογημένος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐρχόμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, bendito aquele que vem em nome do Senhor, 12:13 (Ps 117:26). A passagem do salmo provavelmente tem o mesmo sentido (apesar de Heitmüller 53f) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:9</a>; 23:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:35</a>; 19:38.—OMerlier, <span class=\"greek\">Ὄνομα</span> et <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span> dans le quatr. Év.: RevÉtGr 47, ’34, 180–204; RBratcher, BT 14, ’63, 72–80. <span class=\"hebrew\" dir=\"rtl\">ד</span>. Com <span class=\"greek\">ἕνεκα</span> (e as outras formas dessa palavra; ver <span class=\"greek\">ἕνεκα</span> 1), acerca de perseguições pela fé cristã: <span class=\"greek\">ἀπάγεσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">βασιλεῖς</span> <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, ser levado perante reis por causa do meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:12</a>. <span class=\"greek\">πάσχειν</span> ou <span class=\"greek\">ὑποφέρειν</span> <span class=\"greek\">εἵνεκα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span>, sofrer ou suportar por causa do nome, Hv 3, 1, 9; 3, 2, 1; Hs 9, 28, 5. <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">κυρίου</span>, v 3, 5, 2; Hs 9, 28, 6. <span class=\"greek\">ἀφιέναι</span> <span class=\"greek\">οἰκίας</span> … <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">ὀν</span>., deixar casas … por causa de meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:29</a>. <span class=\"greek\">ἔκτισας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">σου</span>, criaste todas as coisas por causa de teu nome, isto é, para que o nome de Deus seja louvado pelos benefícios que a criação proporciona à humanidade, D 10:3. <span class=\"hebrew\" dir=\"rtl\">ה</span>. Com <span class=\"greek\">ἐπί</span> e dativo: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τινος</span>, quando o nome de alguém é mencionado ou invocado, ou mencionando o nome de alguém (LXX; En 10:2; Just., D. 39, 6; Ath. 23, 1; ver Heitmüller 19ff; 43ff; ver também 47ff; 52ff; 87ff); no NT, somente do nome de Jesus, e somente nos Sinóticos e em Ac. <span class=\"greek\">ἐλεύσονται</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, virão usando meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a>. <span class=\"greek\">κηρύσσειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">μετάνοιαν</span>, pregar arrependimento em seu nome, 24:47. <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τούτῳ</span>, falar usando esse nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:17</a>; 5:40. <span class=\"greek\">διδάσκειν</span>, ensinar, 4:18; 5:28. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">δύναμιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, realizar obra poderosa em meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:39</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">σου</span> <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">δαιμόνια</span>, expulsar demônios em teu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:49</a>, variante de leitura. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">θεραπείας</span> <span class=\"greek\">ἐπετέλουν</span>, realizavam curas em teu nome, GJs 20:2 (códices). Acerca do templo (espiritual) de Deus: <span class=\"greek\">οἰκοδομηθήσεται</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐνδόξως</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">κυρίου</span>, o templo de Deus será gloriosamente edificado mediante o uso do nome do Senhor, 16:6f, 8 (citação de origem incerta). <span class=\"greek\">βαπτίζεσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:38</a>. Também se faz referência ao batismo em <span class=\"greek\">καλεῖσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, receber um nome quando se pronuncia o nome do Filho de Deus, Hs 9, 17, 4. Também podem ser incluídas aqui as palavras <span class=\"greek\">δέχεσθαι</span> (<span class=\"greek\">παιδίον</span>) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, receber (uma criança) quando meu nome é confessado, quando sou invocado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a> (ver Heitmüller 64); mas ver também 3 abaixo.—<span class=\"greek\">ἐπί</span> com acusativo: <span class=\"greek\">πεποιθέναι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὁσιώτατον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγαλωσύνης</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὄν</span>., confiar no nome santíssimo e majestoso (do Senhor), 1 Cl 58:1b; <span class=\"greek\">ἐλπίζειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>., esperar no nome (do Senhor), 16:8b. <span class=\"hebrew\" dir=\"rtl\">ו</span>. Com <span class=\"greek\">περί</span> e genitivo: <span class=\"greek\">εὐαγγελίζεσθαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χ</span>., anunciar as boas-novas acerca do nome de Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:12</a>.—(Com acusativo: <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">δέος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, Orig., C. Cels. 4, 48, 34). <span class=\"hebrew\" dir=\"rtl\">ז</span>. Com <span class=\"greek\">πρός</span> e acusativo: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">Ἰησοῦ</span> … <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐναντία</span> <span class=\"greek\">πρᾶξαι</span>, realizar muitas ações contrárias ao nome de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:9</a>. <span class=\"hebrew\" dir=\"rtl\">ח</span>. Com <span class=\"greek\">ὑπέρ</span> e genitivo: <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. (<span class=\"greek\">Ἰησοῦ</span>) <span class=\"greek\">ἀτιμασθῆναι</span>, ser desonrado por causa do nome (de Jesus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:41</a>. <span class=\"greek\">πάσχειν</span>, sofrer, 9:16; Hs 9, 28, 2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:26</a>; 21:13. A atividade dos apóstolos se realiza <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">αὐτοῦ</span>, para honra do nome (de Jesus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>. Cf. 3J 7. Quanto à oração de agradecimento na Ceia do Senhor: <span class=\"greek\">εὐχαριστοῦμεν</span> <span class=\"greek\">σοι</span> … <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">σου</span>, <span class=\"greek\">οὗ</span> <span class=\"greek\">κατεσκήνωσας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">ἡμῶν</span>, damos-te graças … por teu santo nome, que fizeste habitar em nossos corações, D 10:2. <span class=\"greek\">δ</span>. <span class=\"greek\">ὄν</span>. em referência a Deus ou Cristo não raras vezes aparece isoladamente, simplesmente «o Nome»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:9</a> (cf. Diod S 3, 61, 6); 3J 7; 2 Cl 13:1, 4; IEph 3:1; 7:1; IPhld 10:1; Hv 3, 2, 1; Hs 8, 10, 3; 9, 13, 2; 9, 28, 3; 5. ② Uma pessoa (Phalaris, Ep. 128; POxy 1188, 8 [13 d.C.]; BGU 113, 11; Jos., Ant. 14, 22; outros exemplos em Dssm., NB 24f [BS 196f]; LXX): <span class=\"greek\">τὸ</span> <span class=\"greek\">ποθητόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὄν</span>., meu querido amigo: Alce, ISm 13:2; IPol 8:3; Crocus, IRo 10:1. Plural (PThéad 41, 10; PSI 27, 22; Num 1:18 e outros), pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:4</a>. <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">ἀνθρώπων</span>, 11:13 (cf. Ael. Aristid. 50, 72 K.=26 p. 523 D.: <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">ἀνδρῶν</span>). Provavelmente também pertence aqui <span class=\"greek\">περὶ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀνομάτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νόμου</span>, acerca do ensino, de pessoas e da lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:15</a>. ③ Classificação à qual alguém pertence, indicada por um nome ou categoria, título, categoria (cf. Cass. Dio 38, 44; 42, 24 <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">πλείω</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σχήματι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">στρατηγίας</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">καταπράξειν</span> <span class=\"greek\">ἤλπιζε</span> = esperava realizar muito mais, aproveitando suas vestes e título de pretor; inscrição: Sb 7541, 5 [II d.C.] <span class=\"greek\">Νύμφη</span> <span class=\"greek\">ὄνομ</span>’ <span class=\"greek\">ἐστί</span> <span class=\"greek\">σοι</span>; POxy 37 I, 17 [49 d.C.] <span class=\"greek\">βούλεται</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">ἐλευθέρου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σωμάτιον</span> <span class=\"greek\">ἀπενέγκασθαι</span> = ela afirma ter levado a criança com base em sua condição de nascida livre; Jos., Ant. 12, 154 <span class=\"greek\">φερνῆς</span> <span class=\"greek\">ὀνόματι</span>; 11, 40; Just., A II, 6, 4 <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρος</span> <span class=\"greek\">ὄνομα</span>. Outros exemplos em Heitmüller 50); a possibilidade de entender <span class=\"greek\">ὄν</span>. como categoria facilitou aos gregos a adoção do rabínico <span class=\"hebrew\" dir=\"rtl\">לְשֵׁם</span> (ver 1d <span class=\"greek\">γ</span> <span class=\"hebrew\" dir=\"rtl\">ב</span> acima), no sentido de «em referência a determinada característica», e depois simplesmente «com referência a», «por causa de»: <span class=\"greek\">ὁ</span> <span class=\"greek\">δεχόμενος</span> <span class=\"greek\">προφήτην</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">προφήτου</span>, aquele que recebe um profeta na categoria de «profeta», isto é, por ser profeta, como profeta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:41a</a>; cf. versículos 41b, 42.—<span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ποτίσῃ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span>, <span class=\"greek\">ὄτι</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">ἐστε</span>, aquele que vos der de beber por pertencerdes à categoria dos que são de Cristo, isto é, na qualidade de seguidores de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:41</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">ὀνειδίζεσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">Χριστοῦ</span>, se sois insultados por causa de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:14</a>. <span class=\"greek\">δοξαζέτω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">τούτῳ</span>, glorifique a Deus nessa condição (= <span class=\"greek\">ὡς</span> <span class=\"greek\">Χριστιανός</span>), versículo 16. <span class=\"greek\">δέδεμαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>., estou preso por causa do Nome, IEph 3:1.—<span class=\"greek\">δέχεσθαι</span> (<span class=\"greek\">παιδίον</span>) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀν</span>. <span class=\"greek\">μου</span>, receber (uma criança) por causa de meu nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a> (cf. Heitmüller 113. Mas ver 1d <span class=\"greek\">γ</span> <span class=\"hebrew\" dir=\"rtl\">ה</span> acima). ④ Reconhecimento concedido a uma pessoa com base no desempenho, nome (bem conhecido), reputação, fama (Hom. e outros; 1 Ch 14:17; 1 Macc 8:12): <span class=\"greek\">φανερὸν</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">αὐτοῦ</span>, sua fama se difundiu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:14</a>. <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἔχειν</span> (Pla., Apol. 38c, Ep. 2, 312c) seguido de <span class=\"greek\">ὅτι</span>, ter reputação de, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:1</a>, talvez também 3:5 (ver 1b <span class=\"greek\">α</span>; JFuller, JETS 26, ’83, 297–306). ⑤ Nome em relação ao cargo exercido, cargo, ofício (POxy 58, 6): <span class=\"greek\">στασιαζουσῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φυλῶν</span>, <span class=\"greek\">ὁποία</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐνδόξῳ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">κεκοσμημένη</span>, quando as tribos disputavam qual delas seria adornada com aquele cargo glorioso, 1 Cl 43:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπισκοπῆς</span>, o cargo de supervisão, 44:1.—B. 1263f. OEANE IV 91–96, sobre práticas mesopotâmicas. Schmidt, Syn. I 113–24. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνομάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνομάζω</span> (<span class=\"greek\">ὄνομα</span>), futuro, 3ª pessoa singular, <span class=\"greek\">ὀνομάσει</span>, Is 62:2; 1 aoristo <span class=\"greek\">ὠνόμασα</span>. Passiva: 1 futuro, 3ª pessoa singular, <span class=\"greek\">ὀνομασθήσεται</span>, Jer 3:16; 1 aoristo <span class=\"greek\">ὠνομάσθην</span>; particípio perfeito <span class=\"greek\">ὠνομασμένος</span> (Just.) (Hom. e posteriores). ① Dar um nome, chamar, denominar, com duplo acusativo (Aelian, NA 12, 2; Wsd 2:13; Philo, Gig. 6 e outros; Iren. 1, 1, 3 [Harv. I, 12, 1]; <span class=\"greek\">τὸν</span> <span class=\"greek\">βλάπτοντα</span> <span class=\"greek\">μοιχὸν</span> <span class=\"greek\">ὀνομάζει</span>, «àquele que a prejudica [a alma descrita como noiva], [Deus] chama adúltero», Did., Gen. 86, 22): <span class=\"greek\">οὓς</span> <span class=\"greek\">ἀποστόλους</span> <span class=\"greek\">ὠνόμασεν</span>, aos quais deu o nome de «apóstolos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:14</a> (sobre a leitura, ver JMeier, JBL 116, ’97, 639 n. 11); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:13</a>. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ὠνόμασεν</span> <span class=\"greek\">Πέτρον</span>, a quem chamou Pedro, versículo 14 (cf. Jos., Ant. 1, 213 <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">Ἴσακον</span> <span class=\"greek\">ὠνόμασε</span>.—Olympiodorus, Life of Plato p. 1 Westerm.: o homem anteriormente chamado Aristocles <span class=\"greek\">μετωνομάσθη</span> <span class=\"greek\">Πλάτων</span>, recebeu do mestre o nome Platão; explica-se em seguida a razão disso). <span class=\"greek\">ὠνόμασεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">Μαρία</span>, deu-lhe o nome Maria, GJs 5:2. Passiva com nominativo (Diod S 17, 87, 2 <span class=\"greek\">ὠνομάζετο</span>, <span class=\"greek\">Ἐμβύσαρος</span>; Jos., Vi. 3): <span class=\"greek\">ὠνομάσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">Ἰ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a> D. <span class=\"greek\">τὶς</span> <span class=\"greek\">ἀδελφὸς</span> <span class=\"greek\">ὀνομαζόμενος</span>, alguém chamado membro, um assim chamado membro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:11</a> (cf. 3 Macc 7:17). <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὗ</span> (isto é, <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>) <span class=\"greek\">πᾶσα</span> <span class=\"greek\">πατριὰ</span> … <span class=\"greek\">ὀνομάζεται</span>, de quem toda família … recebe o nome, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:15</a> (para <span class=\"greek\">ὀνομάζειν</span> <span class=\"greek\">ἐκ</span>, cf. Il. 10, 68; para <span class=\"greek\">ὀνομάζεσθαι</span> <span class=\"greek\">ἐκ</span>, X., Mem. 4, 5, 12). ② Pronunciar um nome ou palavra, dizer o nome, empregar um nome ou vocábulo: <span class=\"greek\">πορνεία</span> … <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ὀνομαζέσθω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, imoralidade sexual … nem sequer seja mencionada entre vós (muito menos praticada), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:3</a>. <span class=\"greek\">ὀν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">κυρίου</span>, proferir o nome do Senhor (quase «invocar»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a> (cf. Is 26:13; Jer 20:9; passiva: Orig., C. Cels. 1, 6, 12; 7, 35, 24). <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">ὀνομαζόμενον</span>, todo nome (de um ser transcendente) que é pronunciado (isto é, invocado), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:21</a> (diferentemente, TAllen, NTS 32, ’86, 470–75: Deus é aquele que nomeia). <span class=\"greek\">ὀν</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, pronunciar o nome do Senhor Jesus sobre alguém (para curá-lo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:13</a> (cf. Jer 32:29).—Mencionar pelo nome, PtK 4 p. 15, 32. ③ Na passiva, «ser nomeado» no sentido de ser conhecido (cf. Esth 9:4; 1 Macc 3:9; 14:10; EpArist 124): <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὅπου</span> <span class=\"greek\">ὠνομάσθη</span> <span class=\"greek\">Χριστός</span>, não onde Cristo já era conhecido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:20</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1</a>, variante de leitura.—DELG s.v. <span class=\"greek\">ὄνομα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀνομαστός, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀνομαστός</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀνομάζω</span>; Hom. e outros; LXX; En 16:1; TestJob; Philo; Jos., C. Ap. 1, 36. Sobre a formação, ver Schwyzer I 503), relativo a ter o nome amplamente difundido, ilustre, célebre: <span class=\"greek\">δὸς</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">ὀν</span>., dá-lhe um nome ilustre, GJs 6:2; <span class=\"greek\">ὄνομα</span> <span class=\"greek\">ὀν</span>. (TestJob 4:6; 53:8).—DELG s.v. <span class=\"greek\">ὄνομα</span>. M-M. s.v. <span class=\"greek\">ὀνομάζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄνος, ου</h1><div class=\"entry-meta\"><span>substantivo masculino/feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄνος</span>, <span class=\"greek\">ου</span> (Hom. e posteriores; empréstimo na literatura rabínica), masculino <span class=\"greek\">ὁ</span> e feminino <span class=\"greek\">ἡ</span>, asno doméstico, jumento ou jumenta: <span class=\"greek\">πῶλος</span> <span class=\"greek\">ὄνου</span>, cria de jumento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:15</a> (Just., A I, 32, 6). Com <span class=\"greek\">πῶλος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:2</a> (Iambl. Erot. p. 222, 38 <span class=\"greek\">εὑρόντες</span> <span class=\"greek\">ὄνους</span> <span class=\"greek\">δύο</span>), 5, 7 (KPieper, Zum Einzug Jesu in Jerusalem: BZ 11, 1913, 397–402; FVogel, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:1</a>–11: Blätter für d. Bayerische Gymnasialschulwesen 59, 1923, 212f; ELittmann, ZNW 34, ’35, 28; CSmith, The Horse and the Ass in the Bible: ATR 27, ’45, 86–97; W-S. §27, 3c; ver JSauer s.v. <span class=\"greek\">κάμηλος</span>). Com <span class=\"greek\">βοῦς</span> (Is 1:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:15</a>; 14:5, variante de leitura. <span class=\"greek\">ὄνῳ</span> <span class=\"greek\">καθίσαντες</span> <span class=\"greek\">αὐτόν</span> <span class=\"greek\">ἤγαγον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>, colocaram (Policarpo) sobre um asno e o conduziram à cidade, MPol 8:1. <span class=\"greek\">ἔστρωσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄν</span>., preparou a sela de seu asno, GJs 17:2. <span class=\"greek\">κατάγαγέ</span> <span class=\"greek\">με</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄνου</span>, ajuda-me a descer do asno, 17:3.—B. 172. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄντως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄντως</span>, advérbio do particípio <span class=\"greek\">ὤν</span> (Eur., X., Pla. e posteriores; empréstimo na literatura rabínica), relativo ao que realmente é assim, verdadeiramente, realmente, certamente, de fato. ⓐ Literalmente, como advérbio (PGiss 22, 6; Num 22:37; Jer 3:23; Jos., Bell. 1, 68; Just., D. 74, 2; Ath. 23, 4 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">ὄν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:47</a>; 24:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:21</a>; PtK 4 p. 16, 5. <span class=\"greek\">εἶχον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωάννην</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">ὅτι</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">ἦν</span>, consideravam que João era realmente profeta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:32</a>. ⓑ Usado atributivamente (Pla., Phdr. 260a, Clit. 409e; SIG 893b, 8f <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">Ἡρακλείδην</span>; PStras 53 em Novae Comoed. Fgm., ed. OSchröder=Kl. T. 135 p. 47, 14 <span class=\"greek\">ὄν</span>. <span class=\"greek\">θεός</span>; Sb 3924, 39; Philo, Poster. Cai. 167; Jos., Ant. 15, 63 <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">βασιλεῖς</span>; Ar. 4, 1 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">θεοῦ</span>, Just., Ath.; Schwyzer II 415): <span class=\"greek\">ἡ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">χήρα</span>, a viúva verdadeira (aquela desprovida de recursos, em contraste com quem dispõe de recursos, como parentes, ou ainda está em idade de casar, ou, segundo alguns, já foi casada várias vezes), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:3</a>, 5, 16. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">ζωή</span>, a vida real, verdadeira, 6:19. Em contraste, <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">θάνατος</span>, Dg 10:7. <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄν</span>. <span class=\"greek\">ἀποφεύγοντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:18</a>, variante de leitura.—DELG s.v. <span class=\"greek\">εἰμί</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀξίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀξίζω</span> (de <span class=\"greek\">ὄξος</span> por intermédio de <span class=\"greek\">ὀξί</span>, «recipiente de vinagre»), 1 aoristo <span class=\"greek\">ὤξισα</span> (Soranus p. 69, 25; 70, 14; Diosc. 1, 115, 2; 5, 6, 14; Paradoxogr. Flor. 20; Geopon. 5, 29, 4; 7, 15, 6), azedar, adquirir sabor de vinagre, acerca de jarros de vinho pela metade: <span class=\"greek\">ὀξίζουσι</span>, azedam, Hm 12, 5, 3b. Por isso seu dono teme <span class=\"greek\">μήποτε</span> <span class=\"greek\">ὤξισαν</span>, que eles tenham azedado, 12, 5, 3a.—DELG s.v. <span class=\"greek\">ὀξύ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄξος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄξος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (sobre a relação com <span class=\"greek\">ὀξύς</span>, ver Schwyzer I 512, cf. 463; desde Solon 26, 7 Diehl 3, Aeschyl., Hippocr.; papiros, LXX, ApcEsdr; Philo, Aet. M. 113; Mel., P. 80, 582 e outros), vinho azedo, vinagre de vinho; saciava a sede mais eficazmente que água e, sendo mais barato que o vinho comum, era bebida apreciada pelas classes sociais inferiores e pelas pessoas de recursos modestos (Athen. 4, 173e; Plut., Cato Major 336 [1, 13]; Ruth 2:14), especialmente pelos soldados (PLond III, 1245, 9 p. 228 [357 d.C.]). Oferecido a Jesus na cruz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29f</a> (o contraste com o vinho de alta qualidade de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:40</a> provavelmente é intencional). Em 19:29 (ver versículo 28) cumpre-se a Escritura (provavelmente Ps 68:22 <span class=\"greek\">ἐπότισάν</span> <span class=\"greek\">με</span> <span class=\"greek\">ὄξος</span>). Esse ato é interpretado como decorrente da maldade de alguns judeus que o praticaram, e ampliado para uma oferta de fel e vinagre (cf. Ps 68:22; assim também Mel., P. 80, 582f; 93, 706f), em GPt 5:16; 7:5 (ambos <span class=\"greek\">ποτίζειν</span> <span class=\"greek\">χολὴν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὄξους</span>), 3. Entre 7:3 e 5, B cita, como prova de que se ofereceu vinagre, uma passagem profética de resto desconhecida que manda os sacerdotes comer o <span class=\"greek\">ἔντερον</span> <span class=\"greek\">ἄπλυτον</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὄξους</span>, intestino não lavado do bode com vinagre (ver <span class=\"greek\">ἔντερον</span>), 7:4. Com <span class=\"greek\">οἶνος</span> (PLond 856, 28; 1159, 49; outros exemplos em New Docs 1, 85) e misturado a ele, Hm 10, 3, 3.—B. 383. Frisk s.v. <span class=\"greek\">ὄξο</span>. DELG s.v. <span class=\"greek\">ὀξύ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0256-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀξύπτερος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀξύπτερος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀξύς</span>, <span class=\"greek\">πτερόν</span>, «asa»; Aesop, Fab. 8 H.=2 P.), «de asas velozes»; como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀξ</span>., falcão (Cyranides p. 95, 27), B 10:1, 4.</p></section></article>"};
